import {startGame,finishGame} from './engine.mjs?v=1.6-free-1';
export function setupArcade(api){
 const $=s=>document.querySelector(s),pads=[...document.querySelectorAll('[data-pad]')];let round=null,timer=null;
 const board=$('#hunt-board'),dialog=$('#hunt-dialog'),treat=$('#hunt-treat'),rhythm=$('#rhythm-board');
 function moveTreat(){treat.style.left=`${8+Math.random()*Math.max(0,board.clientWidth-70)}px`;treat.style.top=`${8+Math.random()*Math.max(0,board.clientHeight-70)}px`}
 function stop(){clearInterval(timer);timer=null}
 function cancel(){if(!round)return;const id=round.id;stop();round=null;api.sync();if(api.getState().round?.id===id){api.getState().round=null;api.persist()}dialog.close();api.toast('Round ended early. No rewards; practice is always free.')}
 function finish(){if(!round)return;const r=round;round=null;stop();api.sync();const result=finishGame(api.getState(),r.id,r.score);api.persist();api.render();$('#hunt-time').textContent='All done!';$('#hunt-help').textContent=result?`${r.score} points · ${result.practice?'Free practice':`+${result.coins} coins · +${result.xp} XP`}.`:'This round was replaced in another tab. No duplicate reward.';treat.hidden=true;$('#memory-pads').hidden=true;rhythm.hidden=true;$('#hunt-done').hidden=false;api.speak('That was a lovely little adventure!')}
 function update(){if(!round)return;const t=Date.now(),elapsed=t-round.startAt;$('#hunt-time').textContent=`${Math.max(0,Math.ceil((round.duration-elapsed)/1000))}s${round.paid?'':' · Practice'}`;$('#hunt-score').textContent=`${round.score} points`;if(elapsed>=round.duration){finish();return}
  if(round.kind==='hunt'&&t-round.moved>850){moveTreat();round.moved=t}
  if(round.kind==='memory'){const shown=(t-round.showAt)/700,index=Math.floor(shown);pads.forEach((p,i)=>{const active=index>=0&&index<round.sequence.length&&round.sequence[index]===i&&shown%1<.65;p.classList.toggle('lit',active);p.setAttribute('aria-label',`${i+1} ${active?'lit':'flower'}`)});const ready=t>=round.showAt+round.sequence.length*700+300;$('#hunt-help').textContent=ready?'Your turn. Tap the flowers in order, or use keys 1–4.':'Watch the flowers light up. Remember the order.';pads.forEach(p=>p.disabled=!ready)}
  if(round.kind==='rhythm'){round.x=50+Math.sin(elapsed/1000*2.8)*43;$('#firefly').style.left=`${round.x}%`}
 }
 function start(kind){api.sync();const entry=startGame(api.getState(),kind);if(!entry){api.toast('Wake your pet before playing.');return}stop();round={...entry,score:0,moved:0,lastTap:0,sequence:[Math.floor(Math.random()*4),Math.floor(Math.random()*4)],showAt:Date.now()+500,input:0,x:50};api.persist();api.render();$('#arcade-title').textContent={hunt:'Treat hunt',memory:'Memory garden',rhythm:'Firefly rhythm'}[kind];$('#hunt-help').textContent=kind==='hunt'?'Catch moving treats. Finish the round for rewards.':kind==='rhythm'?'Tap or press Space when the firefly enters the gold band. Misses cost a point.':'Watch, remember, repeat.';$('#hunt-done').hidden=true;treat.hidden=kind!=='hunt';$('#memory-pads').hidden=kind!=='memory';rhythm.hidden=kind!=='rhythm';dialog.showModal();board.focus();moveTreat();update();timer=setInterval(update,33)}
 function tap(){if(!round||Date.now()-round.lastTap<400)return;round.lastTap=Date.now();if(round.kind==='hunt'){round.score++;moveTreat();round.moved=Date.now();api.sound()}else if(round.kind==='rhythm'){const distance=Math.abs(round.x-50);if(distance<5.3){round.score+=distance<2.5?3:1;$('#hunt-help').textContent=distance<2.5?'Perfect little spark!':'Nice timing!';api.sound()}else{round.score=Math.max(0,round.score-1);$('#hunt-help').textContent='Wait for the gold band. You’ve got this.'}}update()}
 function choose(i){if(!round||round.kind!=='memory'||Date.now()<round.showAt+round.sequence.length*700+300)return;if(i===round.sequence[round.input]){round.input++;api.sound();if(round.input===round.sequence.length){round.score+=round.sequence.length*2;round.sequence.push(Math.floor(Math.random()*4));round.input=0;round.showAt=Date.now()+800}}else{round.score=Math.max(0,round.score-1);round.input=0;round.showAt=Date.now()+800}update()}
 $('#start-hunt').onclick=()=>start('hunt');$('#start-memory').onclick=()=>start('memory');$('#start-rhythm').onclick=()=>start('rhythm');treat.onclick=tap;rhythm.onclick=tap;pads.forEach(p=>p.onclick=()=>choose(Number(p.dataset.pad)));
 dialog.addEventListener('keydown',e=>{if(!round)return;if(round.kind==='rhythm'&&e.code==='Space'){e.preventDefault();if(!e.repeat)tap()}if(round.kind==='memory'&&/^[1-4]$/.test(e.key)){e.preventDefault();if(!e.repeat)choose(Number(e.key)-1)}});
 dialog.addEventListener('close',()=>{if(round)cancel()});return {cancel};
}
